import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Calendar, Users, User, Home, LayoutDashboard, Map as MapIcon, Trophy } from 'lucide-react';
import { useUser } from '../context/UserContext';

interface LayoutProps {
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { role } = useUser();

  const isActive = (path: string, search?: string) => {
    if (search) {
      return location.pathname === path && location.search.includes(search);
    }
    return location.pathname === path;
  };

  const NavItem = ({ path, search, icon: Icon, label }: { path: string, search?: string, icon: any, label: string }) => {
    const active = isActive(path, search);
    return (
      <button
        onClick={() => navigate(search ? `${path}${search}` : path)}
        className="flex flex-col items-center gap-1 group w-16"
      >
        <div className={`p-1 rounded-xl transition-colors ${active ? 'bg-primary/10' : 'group-hover:bg-slate-50 dark:group-hover:bg-slate-800'}`}>
            <Icon 
                size={26} 
                strokeWidth={active ? 2.5 : 2} 
                className={`transition-colors ${active ? 'text-primary fill-current' : 'text-gray-400 group-hover:text-gray-600 dark:group-hover:text-gray-200'}`} 
            />
        </div>
        <span className={`text-[10px] font-medium transition-colors ${active ? 'text-primary' : 'text-gray-400 group-hover:text-gray-600 dark:group-hover:text-gray-200'}`}>
            {label}
        </span>
      </button>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-background-light dark:bg-background-dark overflow-hidden transition-colors duration-200 font-display">

      <main className="flex-1 overflow-y-auto pb-24 no-scrollbar">
        {children}
      </main>

      {/* Bottom Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 z-50 bg-white dark:bg-[#1a2632] border-t border-gray-200 dark:border-gray-800 px-6 py-3 safe-area-pb">
        <div className="flex items-center justify-between">
          {role === 'PLAYER' ? (
            <>
              <NavItem path="/home" icon={Home} label="Home" />
              <NavItem path="/bookings" icon={Calendar} label="Bookings" />
              <NavItem path="/explore-map" icon={MapIcon} label="Explore" />
              <NavItem path="/profile" icon={User} label="Profile" />
            </>
          ) : (
            <>
              <NavItem path="/owner" search="tab=Dashboard" icon={LayoutDashboard} label="Home" />
              <NavItem path="/owner" search="tab=Bookings" icon={Calendar} label="Bookings" />
              <NavItem path="/owner" search="tab=Facilities" icon={Trophy} label="Pitches" />
              <NavItem path="/owner" search="tab=Settings" icon={User} label="Settings" />
            </>
          )}
        </div>
      </nav>
    </div>
  );
};

