import { useUser } from '../context/UserContext';
import { Turf } from '../types';
import { Sparkles, Zap, MapPin, Loader2, User, Star, Wallet, CheckCircle, Users, ArrowRight, ArrowLeft, Clock, AlertTriangle, Calendar, Plus, Trophy, Search, Info, CreditCard, Coins } from 'lucide-react';

// --- TYPES ---
interface Player {
    id: string;
    name: string;
    role: string;
    rating: number;
    avatar: string;
}

interface CommunityMatch {
    id: string;
    title: string;
    description: string;
    organizer: string;
    organizerAvatar: string;
    venue: Turf;
    date: string;
    time: string;
    format: string;
    joined: number;
    maxPlayers: number;
    costPerPerson: number;
    type: 'Friendly' | 'Competitive' | 'Pickup';
    isAiGenerated?: boolean;
    hasJoined?: boolean;
}

export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking(); 
  const { addXP, stats } = useUser();

  // UI States
  const [isScanning, setIsScanning] = useState(false);

  // Create Match Full Page State
  const [isCreating, setIsCreating] = useState(false);
  const [createStep, setCreateStep] = useState(0); 

  // Create Match Local State
  const [turfSearchQuery, setTurfSearchQuery] = useState("");
  const [newMatch, setNewMatch] = useState({
      type: 'Friendly',
      format: '5-a-side',
      duration: 1, // Hours
      venueId: '',
      date: new Date().toISOString().split('T')[0],
      time: '',
      paymentMode: 'Split',
      notes: ''
  });

  // Data States
  const [communityMatches, setCommunityMatches] = useState<CommunityMatch[]>([
      {
          id: 'cm1',
          title: 'Sunday Morning Sweat',
          description: 'Casual game to start the day. Beginners welcome!',
          organizer: 'Coach Mike',
          organizerAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop',
          venue: turfs[0],
          date: '2025-01-20',
          time: '08:00',
          format: '5-a-side',
          joined: 7,
          maxPlayers: 10,
          costPerPerson: 5000,
          type: 'Friendly',
          hasJoined: false
      },
      {
          id: 'cm2',
          title: 'Competitive 7v7',
          description: 'High intensity match. Bring your A-game.',
          organizer: 'Sarah K.',
          organizerAvatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop',
          venue: turfs[2],
          date: '2025-01-20',
          time: '19:00',
          format: '7-a-side',
          joined: 12,
          maxPlayers: 14,
          costPerPerson: 8000,
          type: 'Competitive',
          hasJoined: false
      }
  ]);

  const myTeam = MY_TEAMS[0];

  // --- HELPERS ---
  const hasActiveMatch = useMemo(() => communityMatches.some(m => m.hasJoined), [communityMatches]);

  // Filter Turfs for Search
  const filteredTurfs = useMemo(() => {
      if (!turfSearchQuery) return turfs;
      return turfs.filter(t => 
          t.name.toLowerCase().includes(turfSearchQuery.toLowerCase()) ||
          t.location.toLowerCase().includes(turfSearchQuery.toLowerCase())
      );
  }, [turfs, turfSearchQuery]);

  // Dynamic Time Slots based on Venue Hours + Duration Availability
  const getAvailableSlots = (turfId: string, date: string, duration: number) => {
      const turf = turfs.find(t => t.id === turfId);
      if (!turf) return [];

      const startHour = parseInt(turf.openingHour.split(':')[0]);
      const endHour = parseInt(turf.closingHour.split(':')[0]);
      const slots = [];

      // Check if date is blocked
      if (turf.blockedDates.includes(date)) return [];

      for (let i = startHour; i <= endHour - duration; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          // Check if ANY hour in the duration is booked
          let isBlocked = false;
          for (let d = 0; d < duration; d++) {
             const checkTime = `${(i + d).toString().padStart(2, '0')}:00`;
             const booked = bookings.some(b => 
                b.turfId === turfId && 
                b.date === date && 
                b.time === checkTime &&
                b.status !== 'CANCELLED'
             );
             if (booked) isBlocked = true;
          }

          if (!isBlocked) slots.push(time);
      }
      return slots;
  };

  // --- ACTIONS ---

  const handleJoinMatch = (matchId: string) => {
      // Prevent joining if already in a match
      if (hasActiveMatch) return;

      setCommunityMatches(prev => prev.map(m => {
          if (m.id === matchId && !m.hasJoined && m.joined < m.maxPlayers) {
              addXP(50); // Join Bonus
              return { ...m, joined: m.joined + 1, hasJoined: true };
          }
          return m;
      }));
  };

  const handleCreateSubmit = async () => {
      if (hasActiveMatch) return;
      setIsScanning(true); 

      const selectedTurf = turfs.find(t => t.id === newMatch.venueId) || turfs[0];
      const maxP = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create System Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. AI Gen Title & Description (Mocked for Frontend MVP)
      let aiTitle = `${newMatch.type} at ${selectedTurf.name}`;
      let aiDesc = newMatch.notes || "Join us for a great game!";

      if (!newMatch.notes) {
          try {
              // Using local mock function instead of direct API call
              const result = await generateMatchDetails(newMatch.type, selectedTurf.name, newMatch.paymentMode);
              aiTitle = result.title;
              aiDesc = result.description;
          } catch (e) { console.error("Mock AI Generation failed", e); }
      }

      const newCommunityMatch: CommunityMatch = {
          id: bookingId,
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
          venue: selectedTurf,
          date: newMatch.date,
          time: newMatch.time,
          format: newMatch.format,
          joined: 1,
          maxPlayers: maxP,
          costPerPerson: costPerPerson,
          type: newMatch.type as any,
          hasJoined: true // Creator joins automatically
      };

      setTimeout(() => {
          setCommunityMatches(prev => [newCommunityMatch, ...prev]);
          setIsScanning(false);
          addXP(200);
          setIsCreating(false); 
          setNewMatch({ ...newMatch, time: '', venueId: '', notes: '' });
          setCreateStep(0);
      }, 500); // Small delay to smooth transition
  };

  const renderCreateMatchPage = () => {
    const selectedTurf = turfs.find(t => t.id === newMatch.venueId);
    const availableSlots = selectedTurf 
        ? getAvailableSlots(selectedTurf.id, newMatch.date, newMatch.duration)
        : [];
    const totalCost = selectedTurf ? selectedTurf.pricePerHour * newMatch.duration : 0;
    const maxPlayers = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;

    if (isScanning) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[80vh] bg-slate-50 dark:bg-background-dark p-5">
                <div className="relative">
                    <div className="w-24 h-24 rounded-full border-4 border-slate-200 dark:border-slate-700 animate-spin border-t-primary"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-primary animate-pulse" size={32} />
                    </div>
                </div>
                <h2 className="mt-8 text-2xl font-bold text-slate-900 dark:text-white">Organizing Match...</h2>
                <p className="text-slate-500 dark:text-slate-400 mt-2 text-center max-w-xs">
                    Booking {selectedTurf?.name}, handling payments, and generating invites with AI.
                </p>
            </div>
        )
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-background-dark animate-fadeIn">
            <div className="sticky top-0 z-30 bg-white/80 dark:bg-[#1a2632]/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 p-4 flex items-center justify-between">
                <button 
                    onClick={() => {
                        if(createStep > 0) setCreateStep(createStep - 1);
                        else setIsCreating(false);
                    }}
                    className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
                >
                    <ArrowLeft className="text-slate-900 dark:text-white" />
                </button>
                <div className="flex flex-col items-center">
                    <h2 className="text-slate-900 dark:text-white font-bold">Create Match</h2>
                    <div className="flex space-x-1 mt-1">
                        {[0, 1, 2].map(s => (
                            <div key={s} className={`w-2 h-2 rounded-full transition-colors ${s === createStep ? 'bg-primary' : 'bg-slate-300 dark:bg-slate-700'}`} />
                        ))}
                    </div>
                </div>
                <div className="w-10" />
            </div>

            <div className="p-5 max-w-2xl mx-auto min-h-[calc(100vh-80px)] flex flex-col justify-between">
                <div>
                    {createStep === 0 && (
                        <div className="space-y-8 animate-slideUp">
                            <div>
                                <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-4">What kind of match?</h3>
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                    {['Friendly', 'Competitive', 'Pickup'].map(type => (
                                        <button 
                                            key={type}
                                            onClick={() => setNewMatch({...newMatch, type})}
                                            className={`p-6 rounded-2xl border-2 text-left transition-all relative overflow-hidden group ${
                                                newMatch.type === type 
                                                ? 'border-primary bg-primary/5' 
                                                : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-[#1a2632] hover:border-primary/50'
                                            }`}
                                        >
                                            <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-4 ${newMatch.type === type ? 'bg-primary text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'}`}>
                                                {type === 'Friendly' && <Users size={24} />}
                                                {type === 'Competitive' && <Trophy size={24} />}
                                                {type === 'Pickup' && <Plus size={24} />}
                                            </div>
                                            <h4 className="font-bold text-slate-900 dark:text-white text-lg">{type}</h4>
                                            <p className="text-xs text-slate-500 mt-1">
                                                {type === 'Friendly' ? 'Casual play with friends' : type === 'Competitive' ? 'Ranked match for XP' : 'Open to everyone'}
                                            </p>
                                            {newMatch.type === type && <div className="absolute top-4 right-4 text-primary"><CheckCircle size={20} /></div>}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Format</h3>
                                <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                                    {['5-a-side', '7-a-side', '11-a-side'].map(fmt => (
                                        <button 
                                            key={fmt}
                                            onClick={() => setNewMatch({...newMatch, format: fmt})}
                                            className={`px-6 py-3 rounded-xl font-bold border transition-all whitespace-nowrap ${
                                                newMatch.format === fmt 
                                                ? 'bg-primary text-white border-primary shadow-lg' 
                                                : 'bg-white dark:bg-[#1a2632] text-slate-500 border-slate-200 dark:border-slate-700'
                                            }`}
                                        >
                                            {fmt}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    {createStep === 1 && (
                        <div className="space-y-8 animate-slideUp">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Date</label>
                                    <div className="relative">
                                        <Calendar className="absolute left-4 top-4 text-slate-400" size={20} />
                                        <input 
                                            type="date" 
                                            value={newMatch.date}
                                            onChange={(e) => setNewMatch({...newMatch, date: e.target.value, time: ''})}
                                            className="w-full bg-white dark:bg-[#1a2632] border border-slate-200 dark:border-slate-700 rounded-2xl p-4 pl-12 text-lg font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Duration</label>
                                    <div className="flex gap-2">
                                        {[1, 1.5, 2].map(d => (
                                            <button 
                                                key={d}
                                                onClick={() => setNewMatch({...newMatch, duration: d, time: ''})} 
                                                className={`flex-1 py-4 rounded-2xl font-bold border transition-all ${
                                                    newMatch.duration === d 
                                                    ? 'bg-primary border-primary text-white' 
                                                    : 'bg-white dark:bg-[#1a2632] border-slate-200 dark:border-slate-700 text-slate-500'
                                                }`}
                                            >
                                                {d}h
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div>
                                <div className="flex justify-between items-center mb-4">
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white">Select Venue</h3>
                                    <div className="relative w-1/2">
                                        <input 
                                            type="text" 
                                            placeholder="Search turf..." 
                                            value={turfSearchQuery}
                                            onChange={(e) => setTurfSearchQuery(e.target.value)}
                                            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-lg py-2 pl-8 pr-3 text-xs text-slate-900 dark:text-white focus:ring-1 focus:ring-primary outline-none"
                                        />
                                        <Search className="absolute left-2.5 top-2.5 text-slate-400" size={12} />
                                    </div>
                                </div>

                                <div className="space-y-4 max-h-[300px] overflow-y-auto pr-1">
                                    {filteredTurfs.map(turf => (
                                        <div 
                                            key={turf.id}
                                            onClick={() => setNewMatch({...newMatch, venueId: turf.id, time: ''})}
                                            className={`flex rounded-2xl border cursor-pointer overflow-hidden transition-all ${
                                                newMatch.venueId === turf.id 
                                                ? 'border-primary ring-2 ring-primary/30 bg-primary/5' 
                                                : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-[#1a2632]'
                                            }`}
                                        >
                                            <div className="w-24 h-24 sm:w-32 sm:h-auto bg-slate-200">
                                                <img src={turf.image} className="w-full h-full object-cover" />
                                            </div>
                                            <div className="p-4 flex-1 flex flex-col justify-center">
                                                <div className="flex justify-between items-start mb-1">
                                                    <h4 className="font-bold text-slate-900 dark:text-white">{turf.name}</h4>
                                                    {newMatch.venueId === turf.id && <CheckCircle size={20} className="text-primary" />}
                                                </div>
                                                <p className="text-xs text-slate-500 mb-2">{turf.location}</p>
                                                <div className="flex items-center space-x-3 text-xs">
                                                    <span className="font-bold text-primary">UGX {turf.pricePerHour.toLocaleString()}/hr</span>
                                                    <span className="flex items-center text-slate-400"><Star size={12} className="mr-1 fill-current text-yellow-400" /> {turf.rating}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {newMatch.venueId && (
                                <div className="animate-fadeIn">
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Available Slots ({newMatch.duration}h)</h3>
                                    <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                        {availableSlots.length > 0 ? availableSlots.map(t => (
                                            <button
                                                key={t}
                                                onClick={() => setNewMatch({...newMatch, time: t})}
                                                className={`py-3 rounded-xl text-sm font-bold border transition-all ${
                                                    newMatch.time === t 
                                                    ? 'bg-primary border-primary text-white shadow-md' 
                                                    : 'bg-white dark:bg-[#1a2632] border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300'
                                                }`}
                                            >
                                                {t}
                                            </button>
                                        )) : (
                                            <div className="col-span-full p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-500 text-sm flex items-center justify-center">
                                                <AlertTriangle size={16} className="mr-2" /> No slots available for this duration.
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {createStep === 2 && (
                        <div className="space-y-6 animate-slideUp">
                            <div className="bg-white dark:bg-[#1a2632] rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-xl relative overflow-hidden">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                                <h3 className="text-slate-500 text-xs font-bold uppercase tracking-widest mb-6">Match Summary</h3>
                                <div className="flex items-start mb-6">
                                    <div className="w-16 h-16 rounded-2xl overflow-hidden mr-4 border border-slate-200 dark:border-slate-700">
                                        <img src={selectedTurf?.image} className="w-full h-full object-cover" />
                                    </div>
                                    <div>
                                        <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-1">{selectedTurf?.name}</h2>
                                        <p className="text-slate-500 text-sm flex items-center"><MapPin size={12} className="mr-1" /> {selectedTurf?.location}</p>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-y-4 gap-x-8 text-sm border-t border-slate-100 dark:border-slate-700 pt-6">
                                    <div>
                                        <p className="text-slate-400 text-xs mb-1">Date</p>
                                        <p className="font-bold text-slate-900 dark:text-white flex items-center"><Calendar size={14} className="mr-2 text-primary" /> {newMatch.date}</p>
                                    </div>
                                    <div>
                                        <p className="text-slate-400 text-xs mb-1">Time</p>
                                        <p className="font-bold text-slate-900 dark:text-white flex items-center"><Clock size={14} className="mr-2 text-primary" /> {newMatch.time} ({newMatch.duration}h)</p>
                                    </div>
                                    <div>
                                        <p className="text-slate-400 text-xs mb-1">Format</p>
                                        <p className="font-bold text-slate-900 dark:text-white">{newMatch.format}</p>
                                    </div>
                                    <div>
                                        <p className="text-slate-400 text-xs mb-1">Type</p>
                                        <p className="font-bold text-slate-900 dark:text-white">{newMatch.type}</p>
                                    </div>
                                </div>
                            </div>

                             <div>
                                 <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Match Notes / Instructions</label>
                                 <textarea 
                                    value={newMatch.notes}
                                    onChange={(e) => setNewMatch({...newMatch, notes: e.target.value})}
                                    placeholder="e.g. Bring white bibs, cash for parking..."
                                    className="w-full bg-white dark:bg-[#1a2632] border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none h-20 resize-none"
                                 />
                            </div>

                            <div className="bg-slate-50 dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-700">
                                <h3 className="text-slate-900 dark:text-white font-bold mb-4 flex items-center">
                                    <CreditCard className="mr-2" size={20} /> Payment & Costs
                                </h3>
                                <div className="flex bg-white dark:bg-[#1a2632] p-1 rounded-xl mb-6 border border-slate-200 dark:border-slate-700">
                                    {['Split', 'Single'].map(mode => (
                                        <button 
                                            key={mode}
                                            onClick={() => setNewMatch({...newMatch, paymentMode: mode})}
                                            className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${
                                                newMatch.paymentMode === mode 
                                                ? 'bg-primary text-white shadow-sm' 
                                                : 'text-slate-500 dark:text-slate-400'
                                            }`}
                                        >
                                            {mode} Payment
                                        </button>
                                    ))}
                                </div>
                                {newMatch.paymentMode === 'Split' ? (
                                    <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700 space-y-4">
                                        <div className="flex justify-between items-center pb-4 border-b border-slate-100 dark:border-slate-700">
                                            <span className="text-slate-500 dark:text-slate-400 text-xs">Total Venue Cost</span>
                                            <span className="text-slate-900 dark:text-white font-bold">UGX {totalCost.toLocaleString()}</span>
                                        </div>
                                        <div className="flex justify-between items-center">
                                            <div className="flex flex-col">
                                                <span className="text-slate-900 dark:text-white font-bold text-lg flex items-center">
                                                    <Coins size={16} className="text-primary mr-2" />
                                                    UGX {Math.ceil(totalCost / maxPlayers).toLocaleString()}
                                                </span>
                                                <span className="text-[10px] text-slate-400">per person</span>
                                            </div>
                                            <div className="bg-primary/10 text-primary px-3 py-1 rounded-lg text-xs font-bold">
                                                AI Calculated
                                            </div>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700 flex justify-between items-center">
                                        <div>
                                            <p className="text-xs text-slate-400 mb-1">Total Cost (Organizer pays all)</p>
                                            <p className="text-xl font-bold text-slate-900 dark:text-white">
                                                UGX {totalCost.toLocaleString()}
                                            </p>
                                        </div>
                                        <Info size={20} className="text-slate-400" />
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-700">
                     <button 
                        onClick={() => createStep === 2 ? handleCreateSubmit() : setCreateStep(createStep + 1)}
                        disabled={createStep === 1 && (!newMatch.venueId || !newMatch.time)}
                        className="w-full bg-primary text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-blue-600 disabled:opacity-50 disabled:scale-100 transition-all active:scale-[0.98] flex items-center justify-center"
                     >
                         {createStep === 2 ? 'Confirm & Create Match' : 'Continue'}
                         {createStep !== 2 && <ArrowRight size={20} className="ml-2" />}
                     </button>
                </div>
            </div>
        </div>
    );
  };

  return (
    <Layout>
        {isCreating ? renderCreateMatchPage() : (
            <div className="p-5 pt-8 bg-background-light dark:bg-background-dark min-h-screen text-slate-900 dark:text-white pb-24">
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <h1 className="text-2xl font-bold flex items-center">
                            <Sparkles className="mr-2 text-primary" /> Match Center
                        </h1>
                        <p className="text-slate-500 dark:text-slate-400 text-xs mt-1">Pick-up Games & Friendly Play</p>
                    </div>
                    <div className="bg-white dark:bg-slate-800 p-2 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
                        <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                    </div>
                </div>

