                                <p className={`text-sm mb-4 p-3 rounded-xl italic ${match.hasJoined ? 'bg-emerald-800 text-emerald-100' : 'bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400'}`}>"{match.description}"</p>
