                                                    : 'bg-primary text-white hover:bg-blue-600'
                                            }`}
                                        >
                                            {match.hasJoined ? (
                                                <span className="flex items-center"><CheckCircle size={14} className="mr-1" /> Joined</span>
                                            ) : match.joined >= match.maxPlayers ? 'Full' : 'Join'}
                                        </button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}
    </Layout>
  );
};

