                                <Search size={18} className="text-slate-400 mr-2" />
                                <input 
                                    type="text" 
                                    placeholder={mode === 'FIND_SQUAD' ? "Search teams..." : "Search players..."}
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="bg-transparent border-none outline-none text-sm w-full text-slate-900 dark:text-white"
                                />
                            </div>
                            <button className="bg-slate-100 dark:bg-slate-800 p-2.5 rounded-xl text-slate-500 dark:text-slate-400">
                                <Filter size={20} />
                            </button>
                        </div>

                        <div className="flex space-x-2 overflow-x-auto no-scrollbar">
                            {['All', 'Goalkeeper', 'Defender', 'Midfielder', 'Striker'].map(pos => (
                                <button 
                                    key={pos}
                                    onClick={() => setPositionFilter(pos)}
                                    className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap transition-colors ${
                                        positionFilter === pos 
                                        ? 'bg-primary text-white' 
                                        : 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400'
                                    }`}
                                >
                                    {pos}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Content Grid */}
                <div className="p-5 space-y-4">
                    <div className="flex justify-between items-center">
                        <h2 className="text-slate-900 dark:text-white font-bold text-lg">
                            {mode === 'FIND_SQUAD' ? 'Teams Hiring' : 'Free Agents'}
                        </h2>
                        <span className="text-xs text-slate-500">
                            {mode === 'FIND_SQUAD' ? filteredRequests.length : filteredPlayers.length} results
                        </span>
                    </div>

                    {mode === 'FIND_SQUAD' ? (
                        // --- TEAMS LOOKING FOR PLAYERS ---
                        filteredRequests.map(req => (
                            <div key={req.id} onClick={() => setSelectedRequest(req)} className="bg-white dark:bg-[#1a2632] rounded-2xl p-5 border border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden group cursor-pointer hover:border-primary transition-colors">
                                <div className={`absolute top-0 right-0 w-16 h-16 opacity-10 rounded-bl-full transition-transform group-hover:scale-150 ${
                                    req.urgency === 'High' ? 'bg-red-500' : 'bg-blue-500'
                                }`} />

                                <div className="flex justify-between items-start mb-4">
                                    <div className="flex items-center">
                                        <img src={req.teamLogo} className="w-12 h-12 rounded-xl object-cover border border-slate-200 dark:border-slate-600 mr-3" />
                                        <div>
                                            <h3 className="font-bold text-slate-900 dark:text-white">{req.teamName}</h3>
                                            <p className="text-xs text-slate-500 flex items-center">
                                                <MapPin size={10} className="mr-1" /> {req.location}
                                            </p>
                                        </div>
                                    </div>
                                    <span className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase ${
                                        req.urgency === 'High' ? 'bg-red-500/10 text-red-500' : 'bg-blue-500/10 text-blue-500'
                                    }`}>
                                        {req.urgency} Urgency
                                    </span>
                                </div>

                                <div className="flex items-center justify-between mb-4">
                                    <div className="bg-slate-50 dark:bg-slate-800 p-3 rounded-xl flex-1 mr-2">
                                        <p className="text-[10px] text-slate-400 uppercase font-bold mb-1">Needed</p>
                                        <p className="text-primary font-bold text-sm flex items-center">
                                            {req.position}
                                        </p>
                                    </div>
                                    <div className="bg-slate-50 dark:bg-slate-800 p-3 rounded-xl flex-1 ml-2">
                                        <p className="text-[10px] text-slate-400 uppercase font-bold mb-1">Role</p>
                                        <p className="text-slate-700 dark:text-white font-bold text-sm">{req.role}</p>
                                    </div>
                                </div>

                                <div className="flex items-center justify-between">
                                    <div className="text-xs text-slate-400">
                                        Posted {req.postedAt} • {req.matchType}
                                    </div>
                                    <button className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-5 py-2 rounded-xl text-xs font-bold hover:opacity-90 transition-opacity">
                                        Details
                                    </button>
                                </div>
                            </div>
                        ))
                    ) : (
                        // --- PLAYERS LOOKING FOR TEAMS ---
                        filteredPlayers.map(player => (
                            <div key={player.id} onClick={() => setSelectedPlayer(player)} className="bg-white dark:bg-[#1a2632] rounded-2xl p-4 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col cursor-pointer hover:border-primary transition-colors">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="flex items-center">
                                        <div className="relative mr-3">
                                            <img src={player.avatar} className="w-14 h-14 rounded-full object-cover border-2 border-slate-100 dark:border-slate-600" />
                                            <div className="absolute -bottom-1 -right-1 bg-primary text-white text-[10px] font-bold px-1.5 py-0.5 rounded-md border border-white dark:border-slate-800">
                                                {player.ovr}
                                            </div>
                                        </div>
                                        <div>
                                            <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                                                {player.name}
                                                <CheckCircle size={14} className="ml-1 text-blue-500 fill-current text-white dark:text-black" />
                                            </h3>
                                            <p className="text-xs text-primary font-bold">{player.position}</p>
                                            <p className="text-[10px] text-slate-500">{player.style}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <div className="flex items-center justify-end text-yellow-500 text-xs font-bold mb-1">
                                            <Star size={12} className="fill-current mr-1" /> {player.rating}
                                        </div>
                                        <p className="text-[10px] text-slate-400">Seeking {player.lookingFor}</p>
                                    </div>
                                </div>

                                {/* Stats Bar */}
                                <div className="grid grid-cols-3 gap-2 mb-4">
                                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 text-center">
                                        <span className="block text-[10px] text-slate-400 uppercase">Pace</span>
                                        <span className="font-bold text-slate-700 dark:text-white">{player.stats.pace}</span>
                                    </div>
                                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 text-center">
                                        <span className="block text-[10px] text-slate-400 uppercase">Shoot</span>
                                        <span className="font-bold text-slate-700 dark:text-white">{player.stats.shooting}</span>
                                    </div>
                                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 text-center">
                                        <span className="block text-[10px] text-slate-400 uppercase">Phy</span>
                                        <span className="font-bold text-slate-700 dark:text-white">{player.stats.physical}</span>
                                    </div>
                                </div>

                                <button className="w-full border border-primary text-primary py-3 rounded-xl text-sm font-bold hover:bg-primary hover:text-white transition-colors flex items-center justify-center">
                                    View Profile
                                </button>
                            </div>
                        ))
                    )}

                    {/* Empty State */}
                    {((mode === 'FIND_SQUAD' && filteredRequests.length === 0) || (mode === 'FIND_PLAYERS' && filteredPlayers.length === 0)) && (
                        <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                            <Filter size={48} className="mb-4 opacity-20" />
                            <p className="text-sm">No results found for these filters.</p>
                        </div>
                    )}
                </div>

                {/* FAB to Post Request */}
                <button className="fixed bottom-24 right-5 bg-primary text-white p-4 rounded-full shadow-lg shadow-blue-500/40 hover:scale-110 transition-transform z-40">
                     <Target size={24} />
                </button>
            </div>
        </Layout>
    );
};

import React, { useState } from 'react';
