                                    {isFollowing ? <Check size={16} /> : <Plus size={16} />}
                                </button>
                            </div>
                        </div>

                        <h2 className="text-2xl font-bold mb-4 w-2/3 leading-tight">{t.name}</h2>

                        <div className="flex items-center text-sm font-medium opacity-90 space-x-4">
                             <span className="flex items-center"><Calendar size={14} className="mr-1" /> Jan 14 - Feb 27</span>
