                        <div className="mt-4 pt-4 border-t border-white/20 flex justify-between text-center">
                            <div>
                                <span className="block font-bold text-lg">{t.teams}</span>
                                <span className="text-[10px] uppercase opacity-70">Teams</span>
                            </div>
                            <div>
                                <span className="block font-bold text-lg">{t.matches}</span>
                                <span className="text-[10px] uppercase opacity-70">Matches</span>
                            </div>
                            <div>
                                <span className="block font-bold text-lg">{t.played}</span>
                                <span className="text-[10px] uppercase opacity-70">Played</span>
                            </div>
                        </div>
                    </div>
                )})}
            </div>

            <h3 className="text-slate-900 dark:text-white font-bold mb-3 mt-8">Recent Results (Following)</h3>
            {visibleLiveMatches.length > 0 ? visibleLiveMatches.map(m => (
                <div key={m.id} className="bg-white dark:bg-[#1a2632] rounded-xl p-4 flex items-center justify-between border border-slate-200 dark:border-slate-700 mb-3 shadow-sm">
                     <div className="text-right w-1/3 text-slate-900 dark:text-white font-bold text-sm">{m.homeTeam}</div>
                     <div className="bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-lg text-primary font-bold text-lg border border-slate-200 dark:border-slate-600">
                         {m.homeScore} - {m.awayScore}
                     </div>
                     <div className="text-left w-1/3 text-slate-900 dark:text-white font-bold text-sm">{m.awayTeam}</div>
                </div>
            )) : (
                <p className="text-slate-500 text-sm">No recent results from tournaments you follow.</p>
            )}
        </div>
    </Layout>
  );
};

import React, { useState } from 'react';
import { Layout } from '../components/Layout';
import { ChevronDown, MessageSquare, Send, ArrowLeft, Book, Info, CheckCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

export const Support: React.FC = () => {
    const navigate = useNavigate();
    const [openFaq, setOpenFaq] = useState<number | null>(null);
    const [isSent, setIsSent] = useState(false);

    const FAQs = [
        {
            q: "How do I cancel a booking?",
            a: "Go to the 'Bookings' tab, select the booking you wish to cancel, and tap 'Cancel'. Note that cancellations made less than 2 hours before the slot may incur a fee."
        },
        {
            q: "How does split payment work?",
            a: "When booking, toggle 'Split Payment'. You pay your share immediately. A link is generated for you to share with teammates. They have until the match starts to pay their share."
        },
        {
            q: "What happens if it rains?",
            a: "For outdoor turfs, if the match is cancelled due to heavy rain by the facility owner, you will receive a full refund to your wallet or original payment method."
        },
        {
            q: "How do I create a team?",
            a: "Navigate to the 'Teams' tab and tap the 'Create' button. You can choose a name, logo, and invite members."
        }
    ];

    const handleSendMessage = () => {
        setIsSent(true);
        setTimeout(() => setIsSent(false), 3000);
    };

    return (
        <Layout>
            <div className="min-h-screen bg-background-light dark:bg-background-dark p-5 pt-8 pb-32">
                 <div className="flex items-center mb-6">
                    <button onClick={() => navigate('/profile')} className="mr-4 p-2 bg-white dark:bg-slate-800 rounded-full text-slate-600 dark:text-slate-300">
                        <ArrowLeft size={20} />
                    </button>
                    <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Help & Support</h1>
                </div>

                <div className="bg-primary rounded-2xl p-6 text-white mb-8 shadow-lg relative overflow-hidden">
                    <div className="absolute -right-4 -bottom-4 opacity-20">
                        <MessageSquare size={100} />
                    </div>
                    <h2 className="text-xl font-bold mb-2">We're here to help</h2>
                    <p className="text-blue-100 text-sm mb-4 max-w-[80%]">Having trouble with a booking or account? Send us a message.</p>
                    <button className="bg-white text-primary px-4 py-2 rounded-lg font-bold text-sm shadow-sm hover:bg-blue-50 transition-colors">
                        Chat with Support
                    </button>
                </div>

                <div className="mb-8">
                    <h3 className="text-slate-900 dark:text-white font-bold text-lg mb-4 flex items-center">
                        <Book size={18} className="mr-2 text-slate-400" /> Frequently Asked Questions
                    </h3>
                    <div className="space-y-3">
                        {FAQs.map((faq, idx) => (
                            <div key={idx} className="bg-white dark:bg-[#1a2632] rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700">
                                <button 
                                    onClick={() => setOpenFaq(openFaq === idx ? null : idx)}
                                    className="w-full flex justify-between items-center p-4 text-left font-bold text-sm text-slate-900 dark:text-white"
                                >
                                    {faq.q}
                                    <ChevronDown size={16} className={`text-slate-400 transition-transform ${openFaq === idx ? 'rotate-180' : ''}`} />
                                </button>
                                {openFaq === idx && (
                                    <div className="px-4 pb-4 text-sm text-slate-500 dark:text-slate-400 leading-relaxed border-t border-slate-100 dark:border-slate-700/50 pt-2 bg-slate-50 dark:bg-slate-800/50">
                                        {faq.a}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                <div>
                    <h3 className="text-slate-900 dark:text-white font-bold text-lg mb-4 flex items-center">
                        <Info size={18} className="mr-2 text-slate-400" /> Contact Us
                    </h3>
                    <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                        <div className="space-y-4">
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Subject</label>
                                <select className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-sm text-slate-900 dark:text-white outline-none">
                                    <option>Booking Issue</option>
                                    <option>Payment Problem</option>
                                    <option>Technical Bug</option>
                                    <option>Other</option>
                                </select>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Message</label>
                                <textarea 
                                    placeholder="Describe your issue..."
                                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-sm text-slate-900 dark:text-white outline-none h-32 resize-none"
                                />
                            </div>
                            <button 
                                onClick={handleSendMessage}
                                disabled={isSent}
                                className={`w-full font-bold py-4 rounded-xl flex items-center justify-center transition-all ${isSent ? 'bg-emerald-500 text-white' : 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:opacity-90'}`}
                            >
                                {isSent ? <><CheckCircle size={18} className="mr-2" /> Message Sent</> : <><Send size={18} className="mr-2" /> Send Message</>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

