import React, { useEffect, useState } from 'react';
import { Turf } from '../../types';
import { OwnerService } from '../../services/owner';
import { MapPin, Edit2, Power, Plus, Trash2, CheckCircle, XCircle, Loader2, X, Save, Clock, DollarSign, Image as ImageIcon, Wifi, Car, Zap, Droplets, Beer, ShieldPlus, Users } from 'lucide-react';

const COMMON_AMENITIES = [
    { name: 'Floodlights', icon: Zap },
    { name: 'Parking', icon: Car },
    { name: 'Changing Rooms', icon: Users },
    { name: 'Showers', icon: Droplets },
    { name: 'WiFi', icon: Wifi },
    { name: 'Sports Bar', icon: Beer },
    { name: 'First Aid', icon: ShieldPlus },
    { name: 'Spectator Stand', icon: Users }
];

export const FacilityManager: React.FC = () => {
    const [pitches, setPitches] = useState<Turf[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAdding, setIsAdding] = useState(false);

    // Edit State
    const [editingPitch, setEditingPitch] = useState<Turf | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        loadPitches();
    }, []);

    const loadPitches = async () => {
        const data = await OwnerService.getPitches();
        setPitches(data);
        setLoading(false);
    };

    const handleAddPitch = async () => {
        const name = window.prompt("Enter Pitch Name:");
        if (!name) return;

        setIsAdding(true);
        // Add a mock pitch with defaults
        await OwnerService.addTurf({ name });
        await loadPitches();
        setIsAdding(false);
    };

    const openEditModal = (pitch: Turf) => {
        setEditingPitch({ ...pitch });
    };

    const handleSaveEdit = async () => {
        if (!editingPitch) return;
        setIsSaving(true);

        // Optimistic Update in List
        setPitches(prev => prev.map(p => p.id === editingPitch.id ? editingPitch : p));

        // API Call
        await OwnerService.updateTurfDetails(editingPitch.id, editingPitch);

        setIsSaving(false);
        setEditingPitch(null);
    };

    const toggleAmenity = (amenityName: string) => {
        if (!editingPitch) return;
        const current = editingPitch.amenities || [];
        const updated = current.includes(amenityName) 
            ? current.filter(a => a !== amenityName)
            : [...current, amenityName];
        setEditingPitch({ ...editingPitch, amenities: updated });
    };

    const toggleStatus = async (id: string, currentStatus: string) => {
        const newStatus = currentStatus === 'ACTIVE' ? 'MAINTENANCE' : 'ACTIVE';
        setPitches(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
        await OwnerService.updatePitchStatus(id, newStatus);
    };

    if (loading) return <div className="p-10 text-center text-slate-400">Loading facilities...</div>;

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header */}
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-black italic uppercase text-slate-900 dark:text-white">Your Pitches</h2>
                <button 
                    onClick={handleAddPitch}
                    disabled={isAdding}
                    className="bg-primary text-white px-4 py-3 rounded-xl flex items-center text-xs font-bold uppercase shadow-lg active:scale-95 transition-transform disabled:opacity-50"
                >
                    {isAdding ? <Loader2 className="animate-spin mr-2" size={16}/> : <Plus size={16} className="mr-2" />}
                    Add Pitch
                </button>
            </div>

            {/* List */}
            <div className="grid grid-cols-1 gap-4">
                {pitches.map(pitch => (
                    <div key={pitch.id} className="bg-white dark:bg-[#1a2632] p-4 rounded-3xl border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row items-center gap-6 shadow-sm group hover:border-primary/50 transition-colors">
                        <div className="w-full md:w-32 h-32 rounded-2xl overflow-hidden bg-slate-200 relative">
                            <img src={pitch.image} className={`w-full h-full object-cover transition-all ${pitch.status !== 'ACTIVE' ? 'grayscale' : ''}`} />
                            <div className={`absolute top-2 left-2 px-2 py-1 rounded-lg text-[10px] font-black uppercase ${
                                pitch.status === 'ACTIVE' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white'
                            }`}>
                                {pitch.status}
                            </div>
                        </div>

                        <div className="flex-1 text-center md:text-left">
                            <h3 className="text-lg font-black text-slate-900 dark:text-white uppercase italic">{pitch.name}</h3>
                            <p className="text-slate-500 text-xs flex items-center justify-center md:justify-start mt-1">
                                <MapPin size={12} className="mr-1" /> {pitch.location}
                            </p>
                            <div className="flex gap-4 mt-4 justify-center md:justify-start text-xs">
                                <div className="bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-lg">
                                    <span className="block text-slate-400 font-bold uppercase text-[10px]">Price</span>
                                    <span className="font-bold text-slate-900 dark:text-white">UGX {pitch.pricePerHour.toLocaleString()}</span>
                                </div>
                                <div className="bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-lg">
                                    <span className="block text-slate-400 font-bold uppercase text-[10px]">Hours</span>
                                    <span className="font-bold text-slate-900 dark:text-white">{pitch.openingHour} - {pitch.closingHour}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex gap-2 w-full md:w-auto">
                            <button 
                                onClick={() => openEditModal(pitch)}
                                className="flex-1 md:flex-none p-3 bg-slate-100 dark:bg-slate-700 rounded-xl text-slate-600 dark:text-slate-300 hover:text-primary hover:bg-primary/10 transition-colors"
                                title="Edit Details"
                            >
                                <Edit2 size={18} />
                            </button>
                            <button 
                                onClick={() => toggleStatus(pitch.id, pitch.status)}
                                className={`flex-1 md:flex-none p-3 rounded-xl transition-colors ${
                                    pitch.status === 'ACTIVE' 
                                    ? 'bg-red-50 text-red-500 hover:bg-red-100' 
                                    : 'bg-emerald-50 text-emerald-500 hover:bg-emerald-100'
                                }`}
                                title={pitch.status === 'ACTIVE' ? 'Set to Maintenance' : 'Activate'}
                            >
                                <Power size={18} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingPitch && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white dark:bg-[#1a2632] w-full max-w-2xl rounded-[2rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                        {/* Modal Header */}
                        <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-white dark:bg-[#1a2632]">
                            <h3 className="text-xl font-black italic uppercase text-slate-900 dark:text-white">Edit Facility</h3>
                            <button onClick={() => setEditingPitch(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        {/* Modal Body */}
                        <div className="p-6 overflow-y-auto space-y-6 flex-1 bg-slate-50 dark:bg-background-dark">

                            {/* Section 1: Basic Info */}
                            <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700">
                                <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">General Information</h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Facility Name</label>
                                        <input 
                                            type="text" 
                                            value={editingPitch.name}
                                            onChange={(e) => setEditingPitch({...editingPitch, name: e.target.value})}
                                            className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl p-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Location</label>
                                        <div className="relative">
                                            <MapPin size={14} className="absolute left-3 top-3.5 text-slate-400" />
                                            <input 
                                                type="text" 
                                                value={editingPitch.location}
                                                onChange={(e) => setEditingPitch({...editingPitch, location: e.target.value})}
                                                className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl py-3 pl-9 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                            />
                                        </div>
                                    </div>
                                </div>
                                <div className="mt-4">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Cover Image URL</label>
                                    <div className="relative">
                                        <ImageIcon size={14} className="absolute left-3 top-3.5 text-slate-400" />
                                        <input 
                                            type="text" 
                                            value={editingPitch.image}
                                            onChange={(e) => setEditingPitch({...editingPitch, image: e.target.value})}
                                            className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl py-3 pl-9 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                        />
                                    </div>
                                    {editingPitch.image && (
                                        <div className="mt-2 w-full h-32 rounded-xl overflow-hidden">
                                            <img src={editingPitch.image} className="w-full h-full object-cover opacity-80" alt="Preview" />
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Section 2: Operations */}
                            <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700">
                                <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Operations & Pricing</h4>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    <div>
                                        <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Price Per Hour (UGX)</label>
                                        <div className="relative">
                                            <DollarSign size={14} className="absolute left-3 top-3.5 text-slate-400" />
                                            <input 
                                                type="number" 
                                                value={editingPitch.pricePerHour}
                                                onChange={(e) => setEditingPitch({...editingPitch, pricePerHour: parseInt(e.target.value) || 0})}
                                                className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl py-3 pl-9 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Opens At</label>
                                        <div className="relative">
                                            <Clock size={14} className="absolute left-3 top-3.5 text-slate-400" />
                                            <input 
                                                type="time" 
                                                value={editingPitch.openingHour}
                                                onChange={(e) => setEditingPitch({...editingPitch, openingHour: e.target.value})}
                                                className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl py-3 pl-9 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-bold text-slate-500 uppercase mb-1 block">Closes At</label>
                                        <div className="relative">
                                            <Clock size={14} className="absolute left-3 top-3.5 text-slate-400" />
                                            <input 
                                                type="time" 
                                                value={editingPitch.closingHour}
                                                onChange={(e) => setEditingPitch({...editingPitch, closingHour: e.target.value})}
                                                className="w-full bg-slate-50 dark:bg-slate-700 border-none rounded-xl py-3 pl-9 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-primary outline-none"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Section 3: Amenities */}
                            <div className="bg-white dark:bg-[#1a2632] p-5 rounded-2xl border border-slate-200 dark:border-slate-700">
                                <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Amenities</h4>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    {COMMON_AMENITIES.map((item) => {
                                        const isActive = editingPitch.amenities?.includes(item.name);
                                        const Icon = item.icon;
                                        return (
                                            <button
                                                key={item.name}
                                                onClick={() => toggleAmenity(item.name)}
                                                className={`p-3 rounded-xl flex flex-col items-center justify-center border transition-all ${
                                                    isActive 
                                                    ? 'bg-primary/10 border-primary text-primary' 
                                                    : 'bg-slate-50 dark:bg-slate-700 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-600'
                                                }`}
                                            >
                                                <Icon size={20} className="mb-2" />
                                                <span className="text-[10px] font-bold uppercase text-center">{item.name}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                        </div>

                        {/* Modal Footer */}
                        <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-white dark:bg-[#1a2632] flex gap-3">
                            <button 
                                onClick={() => setEditingPitch(null)}
                                className="flex-1 py-4 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-white rounded-xl font-bold uppercase tracking-widest hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={handleSaveEdit}
                                disabled={isSaving}
                                className="flex-[2] py-4 bg-primary text-white rounded-xl font-bold uppercase tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSaving ? <Loader2 size={18} className="animate-spin mr-2"/> : <Save size={18} className="mr-2"/>}
                                Save Changes
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { Booking } from '../../types';
import { OwnerService } from '../../services/owner';
import { Check, X, Clock, Calendar, User, Search, Filter } from 'lucide-react';

export const BookingManager: React.FC = () => {
    const [bookings, setBookings] = useState<Booking[]>([]);
    const [filter, setFilter] = useState<'ALL' | 'PENDING' | 'CONFIRMED'>('ALL');
    const [processingId, setProcessingId] = useState<string | null>(null);

    useEffect(() => {
        loadBookings();
    }, []);

    const loadBookings = async () => {
        const data = await OwnerService.getBookings();
        setBookings(data);
    };

    const handleAction = async (id: string, action: 'CONFIRMED' | 'CANCELLED') => {
        setProcessingId(id);
        // BACKEND: Verify payment status here before confirming
        await OwnerService.updateBookingStatus(id, action);
        setBookings(prev => prev.map(b => b.id === id ? { ...b, status: action } : b));
        setProcessingId(null);
    };

    const filtered = bookings.filter(b => {
        if (filter === 'ALL') return true;
        return b.status === filter;
    });

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Controls */}
            <div className="flex flex-col md:flex-row gap-4 justify-between">
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl w-full md:w-auto">
                    {['ALL', 'PENDING', 'CONFIRMED'].map((f: any) => (
                        <button
                            key={f}
                            onClick={() => setFilter(f)}
                            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex-1 md:flex-none ${
                                filter === f ? 'bg-white dark:bg-slate-600 shadow-sm text-primary' : 'text-slate-500'
                            }`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
                <div className="relative">
                    <Search size={16} className="absolute left-3 top-3 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Search booking ID..." 
                        className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:border-primary"
                    />
                </div>
            </div>

            {/* List */}
            <div className="space-y-4">
                {filtered.map(booking => (
                    <div key={booking.id} className="bg-white dark:bg-[#1a2632] p-6 rounded-3xl border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row items-center justify-between shadow-sm">
                        <div className="flex items-center gap-4 mb-4 md:mb-0 w-full md:w-auto">
                            <div className="w-12 h-12 bg-slate-100 dark:bg-slate-700 rounded-2xl flex items-center justify-center text-slate-500">
                                <User size={20} />
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-900 dark:text-white text-lg">{booking.userName}</h3>
                                <p className="text-slate-500 text-xs font-mono">{booking.id}</p>
                                <div className="flex items-center gap-3 mt-1 text-xs text-slate-500">
                                    <span className="flex items-center"><Calendar size={12} className="mr-1" /> {booking.date}</span>
                                    <span className="flex items-center"><Clock size={12} className="mr-1" /> {booking.time}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-4 w-full md:w-auto justify-between md:justify-end">
                            <div className="text-right mr-4">
                                <span className={`block text-[10px] font-bold uppercase tracking-widest px-2 py-1 rounded-lg ${
                                    booking.paymentStatus === 'PAID' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
                                }`}>
                                    {booking.paymentStatus}
                                </span>
                                <span className="font-bold text-slate-900 dark:text-white mt-1 block">UGX {booking.price.toLocaleString()}</span>
                            </div>

                            {booking.status === 'PENDING' ? (
                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => handleAction(booking.id, 'CONFIRMED')}
                                        disabled={processingId === booking.id}
                                        className="p-3 bg-emerald-500 text-white rounded-xl hover:bg-emerald-600 disabled:opacity-50"
                                    >
                                        <Check size={20} />
                                    </button>
                                    <button 
                                        onClick={() => handleAction(booking.id, 'CANCELLED')}
                                        disabled={processingId === booking.id}
                                        className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-red-50 hover:text-red-500 disabled:opacity-50"
                                    >
                                        <X size={20} />
                                    </button>
                                </div>
                            ) : (
                                <div className={`px-4 py-2 rounded-xl text-xs font-bold uppercase ${
                                    booking.status === 'CONFIRMED' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-500'
                                }`}>
                                    {booking.status}
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { StaffMember } from '../../types';
import { OwnerService } from '../../services/owner';
import { UserPlus, Shield, Trash2, Phone, Loader2 } from 'lucide-react';

export const StaffManager: React.FC = () => {
    const [staff, setStaff] = useState<StaffMember[]>([]);
    const [isAdding, setIsAdding] = useState(false);

    useEffect(() => {
        load();
    }, []);

    const load = async () => {
        const data = await OwnerService.getStaff();
        setStaff(data);
    };

    const handleAddStaff = async () => {
        const name = window.prompt("Enter Staff Name:");
        if (!name) return;

        setIsAdding(true);
        const newStaff: StaffMember = {
            id: `s-${Date.now()}`,
            name: name,
            role: 'CARETAKER',
            phone: '0700000000'
        };
        await OwnerService.addStaff(newStaff);
        await load();
        setIsAdding(false);
    };

    const handleDeleteStaff = async (id: string) => {
        if (window.confirm("Are you sure you want to remove this staff member?")) {
            setStaff(prev => prev.filter(s => s.id !== id));
            await OwnerService.deleteStaff(id);
        }
    };

    // BACKEND: Permissions check - Only Owner can add staff
    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-black italic uppercase text-slate-900 dark:text-white">Staff Roster</h2>
                <button 
                    onClick={handleAddStaff}
                    disabled={isAdding}
                    className="bg-primary text-white px-4 py-3 rounded-xl flex items-center text-xs font-bold uppercase shadow-lg active:scale-95 disabled:opacity-50"
                >
                    {isAdding ? <Loader2 className="animate-spin mr-2" size={16}/> : <UserPlus size={16} className="mr-2" />}
                    Add Staff
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {staff.map(member => (
                    <div key={member.id} className="bg-white dark:bg-[#1a2632] p-6 rounded-3xl border border-slate-200 dark:border-slate-700 flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-4">
                            <div className="w-14 h-14 bg-slate-100 dark:bg-slate-700 rounded-2xl flex items-center justify-center text-slate-400 overflow-hidden">
                                {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover"/> : <Shield size={24} />}
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-900 dark:text-white text-lg leading-none mb-1">{member.name}</h3>
                                <div className={`inline-flex px-2 py-0.5 rounded-md text-[9px] font-black uppercase ${
                                    member.role === 'MANAGER' ? 'bg-purple-100 text-purple-600' : 'bg-blue-100 text-blue-600'
                                }`}>
                                    {member.role}
                                </div>
                                <p className="text-xs text-slate-500 mt-1 flex items-center">
                                    <Phone size={10} className="mr-1" /> {member.phone}
                                </p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleDeleteStaff(member.id)}
                            className="p-3 hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-xl transition-colors"
                        >
                            <Trash2 size={18} />
                        </button>
                    </div>
                ))}
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-2xl border border-blue-100 dark:border-blue-800 text-sm text-blue-800 dark:text-blue-300">
                <p className="font-bold mb-1">Role Permissions:</p>
                <ul className="list-disc list-inside text-xs opacity-80">
                    <li><strong>Manager:</strong> Can accept bookings, edit pitch details, view revenue.</li>
                    <li><strong>Caretaker:</strong> Can check-in teams, mark pitch maintenance status.</li>
                </ul>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { Settings, Save, Smartphone, Building, CheckCircle, Loader2, Clock } from 'lucide-react';
import { OwnerService } from '../../services/owner';
import { BusinessProfile } from '../../types';

export const BusinessSettings: React.FC = () => {
    const [isSaving, setIsSaving] = useState(false);
    const [saved, setSaved] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Form State
    const [formData, setFormData] = useState<BusinessProfile>({
        businessName: '',
        contactEmail: '',
        contactPhone: '',
        mobileMoneyNumber: '',
        operatingHours: { open: '08:00', close: '23:00' }
    });

    useEffect(() => {
        const load = async () => {
            const data = await OwnerService.getBusinessProfile();
            setFormData(data);
            setIsLoading(false);
        };
        load();
    }, []);

    const handleChange = (field: keyof BusinessProfile, value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleHoursChange = (type: 'open' | 'close', value: string) => {
        setFormData(prev => ({ 
            ...prev, 
            operatingHours: { ...prev.operatingHours, [type]: value } 
        }));
    };

    const handleSave = async () => {
        setIsSaving(true);
        await OwnerService.updateBusinessProfile(formData);
        setIsSaving(false);
        setSaved(true);
        setTimeout(() => setSaved(false), 3000);
    };

    if (isLoading) return <div className="p-10 text-center animate-pulse text-slate-400">Loading settings...</div>;

    return (
        <div className="space-y-6 animate-fadeIn pb-24">
            <h2 className="text-xl font-black italic uppercase text-slate-900 dark:text-white">Business Profile</h2>

            <div className="bg-white dark:bg-[#1a2632] p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm space-y-4">
                <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Business Name</label>
                    <div className="flex items-center bg-slate-50 dark:bg-slate-700 rounded-xl px-4 py-3">
                        <Building size={16} className="text-slate-400 mr-3"/>
                        <input 
                            type="text" 
                            value={formData.businessName}
                            onChange={(e) => handleChange('businessName', e.target.value)}
                            className="bg-transparent w-full text-sm font-bold outline-none text-slate-900 dark:text-white" 
                        />
                    </div>
                </div>

                <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Payout Method (MoMo)</label>
                    <div className="flex items-center bg-slate-50 dark:bg-slate-700 rounded-xl px-4 py-3">
                        <Smartphone size={16} className="text-slate-400 mr-3"/>
                        <input 
                            type="text" 
                            value={formData.mobileMoneyNumber}
                            onChange={(e) => handleChange('mobileMoneyNumber', e.target.value)}
                            className="bg-transparent w-full text-sm font-bold outline-none text-slate-900 dark:text-white" 
                        />
                    </div>
                </div>

                <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Operating Hours</label>
                    <div className="flex gap-4">
                        <div className="flex-1 relative">
                            <Clock size={16} className="absolute left-3 top-3.5 text-slate-400 pointer-events-none"/>
                            <input 
                                type="time" 
                                value={formData.operatingHours.open}
                                onChange={(e) => handleHoursChange('open', e.target.value)}
                                className="bg-slate-50 dark:bg-slate-700 rounded-xl pl-10 pr-4 py-3 w-full text-sm font-bold outline-none text-slate-900 dark:text-white" 
                            />
                        </div>
                        <span className="self-center font-bold text-slate-400">TO</span>
                        <div className="flex-1 relative">
                            <Clock size={16} className="absolute left-3 top-3.5 text-slate-400 pointer-events-none"/>
                            <input 
                                type="time" 
                                value={formData.operatingHours.close}
                                onChange={(e) => handleHoursChange('close', e.target.value)}
                                className="bg-slate-50 dark:bg-slate-700 rounded-xl pl-10 pr-4 py-3 w-full text-sm font-bold outline-none text-slate-900 dark:text-white" 
                            />
                        </div>
                    </div>
                </div>
            </div>

            <button 
                onClick={handleSave}
                disabled={isSaving}
                className={`w-full py-4 rounded-xl font-bold flex items-center justify-center shadow-lg active:scale-95 transition-all ${
                    saved ? 'bg-emerald-500 text-white' : 'bg-primary text-white'
                }`}
            >
                {isSaving ? (
                    <Loader2 size={18} className="mr-2 animate-spin" />
                ) : saved ? (
                    <CheckCircle size={18} className="mr-2" />
                ) : (
                    <Save size={18} className="mr-2" />
                )}
                {isSaving ? 'Saving...' : saved ? 'Changes Saved' : 'Save Changes'}
            </button>
        </div>
    );
};

