interface LayoutProps {
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { role } = useUser();

  const isActive = (path: string, search?: string) => {
    if (search) {
      return location.pathname === path && location.search.includes(search);
    }
    return location.pathname === path;
  };

  const NavItem = ({ path, search, icon: Icon, label }: { path: string, search?: string, icon: any, label: string }) => {
    const active = isActive(path, search);
    return (
      <button
        onClick={() => navigate(search ? `${path}${search}` : path)}
        className="flex flex-col items-center gap-1 group flex-1"
      >
        <div className={`p-1.5 rounded-xl transition-colors ${active ? '' : 'group-hover:bg-slate-50 dark:group-hover:bg-slate-800'}`}>
            <Icon 
                size={24} 
                strokeWidth={active ? 2.5 : 2} 
                className={`transition-colors ${active ? 'text-emerald-500' : 'text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200'}`} 
            />
        </div>
        <span className={`text-[10px] font-bold transition-colors ${active ? 'text-emerald-500' : 'text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200'}`}>
            {label}
        </span>
      </button>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-background-light dark:bg-background-dark overflow-hidden transition-colors duration-200 font-display">

      <main className="flex-1 overflow-y-auto pb-24 no-scrollbar">
        {children}
      </main>

      {/* Bottom Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 z-50 bg-white dark:bg-[#1a2632] border-t border-slate-100 dark:border-slate-800 px-2 py-2 safe-area-pb shadow-[0_-4px_20px_-4px_rgba(0,0,0,0.05)]">
        <div className="flex items-center justify-between max-w-md mx-auto">
          {role === 'PLAYER' ? (
            <>
              <NavItem path="/home" icon={Home} label="Home" />
              <NavItem path="/bookings" icon={Calendar} label="Bookings" />

              {/* FAB */}
              <div className="relative -top-6 group">
                  <button 
                    onClick={() => navigate('/match-center')}
                    className="flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500 text-white shadow-xl shadow-emerald-500/40 hover:bg-emerald-600 hover:scale-105 active:scale-95 transition-all border-4 border-slate-50 dark:border-[#101922]"
                  >
                      <Plus size={28} strokeWidth={2.5} />
                  </button>
              </div>

              <NavItem path="/explore-map" icon={MapIcon} label="Explore" />
              <NavItem path="/profile" icon={User} label="Profile" />
            </>
          ) : (
            <>
              <NavItem path="/owner" search="tab=Dashboard" icon={LayoutDashboard} label="Home" />
              <NavItem path="/owner" search="tab=Bookings" icon={Calendar} label="Bookings" />
              <div className="w-12"></div> {/* Spacer for potential FAB in future */}
