                  <span className="absolute -bottom-4 left-1/2 -translate-x-1/2 text-[10px] font-bold text-primary opacity-0 group-hover:opacity-100 transition-opacity">Explore</span>
              </div>

              {/* Teams Tab (Replaces old Explore position) */}
              <NavItem path="/teams" icon={Shield} label="Teams" />

              <NavItem path="/profile" icon={User} label="Profile" />
            </>
          ) : (
            <>
              <NavItem path="/owner" search="tab=Dashboard" icon={LayoutDashboard} label="Home" />
              <NavItem path="/owner" search="tab=Bookings" icon={Calendar} label="Bookings" />
              <div className="w-12"></div> {/* Spacer for symmetry if needed, or we can add a central action for owners later */}
              <NavItem path="/owner" search="tab=Facilities" icon={Trophy} label="Pitches" />
              <NavItem path="/owner" search="tab=Settings" icon={User} label="Settings" />
