const ScheduleItem = ({ time, title, status, statusColor, organizer, pitch, note }: any) => {
    const colors = {
        green: { dot: 'bg-green-500', badge: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400', border: 'border-green-500' },
        orange: { dot: 'bg-orange-400', badge: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400', border: 'border-orange-400' },
        blue: { dot: 'bg-blue-500', badge: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400', border: 'border-blue-500' },
    };
    const c = colors[statusColor as keyof typeof colors];

    return (
        <div className="flex gap-4 relative group">
            <div className="flex flex-col items-end w-9 pt-1">
                <span className="text-xs font-bold text-[#111418] dark:text-white">{time}</span>
                <span className="text-[10px] text-gray-400">PM</span>
            </div>
            <div className={`relative z-10 size-3 mt-1.5 rounded-full border-2 border-white dark:border-[#101922] ${c.dot} shadow-sm`}></div>
            <div className={`flex-1 bg-white dark:bg-[#1a2632] rounded-xl p-3 border-l-4 ${c.border} shadow-sm hover:shadow-md transition-shadow`}>
                <div className="flex justify-between items-start mb-1">
                    <h4 className="font-bold text-sm text-[#111418] dark:text-white">{title}</h4>
                    <span className={`${c.badge} text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide`}>{status}</span>
                </div>
                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mb-2">
                    <span>{organizer}</span>
                    <span className="w-1 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></span>
                    <span>{pitch}</span>
                </div>
                {note && (
                    <div className="h-6 w-full bg-gray-100 dark:bg-gray-800 rounded flex items-center px-2">
                        <span className="text-[10px] text-gray-500 dark:text-gray-400">{note}</span>
                    </div>
                )}
            </div>
        </div>
    );
};

